<script setup lang="ts">
import {isDesktopClient} from '../services/serverConfig'
import {onBeforeUnmount,onMounted,ref,shallowRef} from 'vue'
import type {AttachmentItem} from '../services/attachments'
import {diagnoseAttachment,attachmentDiagnosticReport,attachmentErrorCode,attachmentErrorMessage,diagnosticOpen,diagnosticSaveAs,redownloadAttachment,revealAttachmentFolder,recordAttachmentAttempt,recentAttachmentAttempts,type AttachmentDiagnostic} from '../services/attachmentDiagnostics'
import {copyLearningText} from '../services/learningClipboard'
import {saveLocalExport} from '../services/localFileExport'
const props=defineProps<{ownerId:string;item:AttachmentItem}>(),emit=defineEmits<{close:[]}>()
const report=shallowRef<AttachmentDiagnostic>(),busy=ref(false),notice=ref(''),reportText=ref('');let alive=true
async function check(){busy.value=true;notice.value='';try{const value=await diagnoseAttachment(props.ownerId,props.item);if(alive){report.value=value;reportText.value=attachmentDiagnosticReport(value)}}catch(error){if(alive)notice.value=attachmentErrorMessage(attachmentErrorCode(error))}finally{if(alive)busy.value=false}}
async function action(kind:'open'|'save'|'reveal'|'download'|'copy'|'export'){
 if(busy.value)return;busy.value=true;notice.value=''
 try{
  if(kind==='open'){await diagnosticOpen(props.ownerId,props.item);notice.value=isDesktopClient()?'已提交系统打开请求，请确认文件是否已显示。':'已提交浏览器下载请求，请在下载列表中查看。'}
  else if(kind==='save'){notice.value=await diagnosticSaveAs(props.ownerId,props.item)?'附件已另存。':'已取消另存。'}
  else if(kind==='reveal'){await revealAttachmentFolder(props.ownerId,props.item);notice.value='已请求打开所在文件夹。'}
  else if(kind==='download'){await redownloadAttachment(props.ownerId,props.item);recordAttachmentAttempt(props.ownerId,props.item,'download','VERIFIED');const value=await diagnoseAttachment(props.ownerId,props.item);if(alive){report.value=value;notice.value='副本校验通过，已重新保存；原文件保留。'}}
  else if(kind==='copy'){await copyLearningText(reportText.value);notice.value='诊断信息已复制。'}
  else notice.value=await saveLocalExport(new Blob([reportText.value],{type:'application/json'}),'attachment-diagnostic.json')?'诊断报告已导出。':'已取消导出。'
 }catch(error){notice.value=kind==='copy'?'复制失败，可展开诊断信息手动复制。':attachmentErrorMessage(attachmentErrorCode(error));if(kind==='download'||kind==='reveal')recordAttachmentAttempt(props.ownerId,props.item,kind==='download'?'download':'reveal',attachmentErrorCode(error))}
 finally{if(alive){if(report.value){report.value={...report.value,recent:recentAttachmentAttempts(props.ownerId,props.item)};reportText.value=attachmentDiagnosticReport(report.value)}busy.value=false}}
}
function keydown(event:KeyboardEvent){if(event.key==='Tab'){const elements=[...document.querySelectorAll<HTMLElement>('.attachment-diagnostic button:not(:disabled),.attachment-diagnostic summary,.attachment-diagnostic textarea')];const first=elements[0],last=elements.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}if(event.key==='Escape'){event.stopImmediatePropagation();emit('close')}}
const previous=document.activeElement as HTMLElement|null
onMounted(()=>{document.querySelector<HTMLElement>('.attachment-diagnostic')?.focus();window.addEventListener('keydown',keydown,true);void check()})
onBeforeUnmount(()=>{alive=false;window.removeEventListener('keydown',keydown,true);previous?.focus()})
</script>
<template><Teleport to="body"><div class="diagnostic-mask" @click.self="emit('close')"><section class="attachment-diagnostic" role="dialog" aria-modal="true" aria-labelledby="diagnostic-title" tabindex="-1"><header><div><h2 id="diagnostic-title">检查附件</h2><p>{{item.originalFilename}}</p></div><button aria-label="关闭检查附件" @click="emit('close')">×</button></header><main><p v-if="busy" role="status">正在检查，请稍候…</p><ol v-if="report"><li v-for="check in report.checks" :key="check.stage" :data-state="check.state"><span>{{check.state==='pass'?'✓':check.state==='fail'?'!':check.state==='warning'?'△':'—'}}</span><div><b>{{check.stage}}</b><p>{{check.message}}</p><small>{{check.code}}</small></div></li></ol><p v-if="report?.environment" class="environment">{{report.environment.distribution||report.environment.os}} · 客户端 {{report.version}} · {{report.environment.packageType==='unknown'?'安装包类型未识别':report.environment.packageType}}</p><details v-if="report?.recent.length"><summary>最近打开记录（当前会话）</summary><p v-for="(attempt,index) in report.recent" :key="index">{{new Date(attempt.at).toLocaleTimeString()}} · {{({preview:'预览',system:'系统打开',download:'重新下载',reveal:'打开文件夹'})[attempt.action]}} · {{attempt.code}}</p></details><p v-if="notice" role="status" class="notice">{{notice}}</p><details v-if="report"><summary>诊断信息（不含密钥、正文、文件名和个人路径）</summary><textarea readonly :value="reportText" aria-label="诊断信息"/></details></main><footer><div><button :disabled="busy" @click="check">重新检查</button><button :disabled="busy||!report?.readable" @click="action('open')">{{isDesktopClient()?'重试打开':'下载后打开'}}</button><button :disabled="busy||!report?.readable" @click="action('save')">另存为</button><button v-if="report?.canReveal" :disabled="busy" @click="action('reveal')">打开所在文件夹</button><button v-if="report?.canRedownload" :disabled="busy" @click="action('download')">重新下载</button></div><div><button :disabled="busy||!report" @click="action('export')">导出报告</button><button class="primary" :disabled="busy||!report" @click="action('copy')">复制诊断信息</button></div></footer></section></div></Teleport></template>
<style scoped>
.diagnostic-mask{position:fixed;inset:0;z-index:1400;display:grid;place-items:center;padding:20px;background:#10251e66}.attachment-diagnostic{width:min(660px,100%);max-height:calc(100dvh - 40px);display:flex;flex-direction:column;border:1px solid var(--pc-border,#dce5df);border-radius:14px;background:var(--pc-surface,#fff);color:var(--pc-text,#263b31);box-shadow:0 24px 80px #10251e33;outline:0}.attachment-diagnostic header{display:flex;justify-content:space-between;align-items:start;padding:20px 24px;border-bottom:1px solid #e6ece8}.attachment-diagnostic h2{margin:0;font-size:18px}.attachment-diagnostic header p{max-width:500px;margin:8px 0 0;overflow-wrap:anywhere;color:#738078}.attachment-diagnostic main{padding:16px 24px;overflow:auto;min-height:0}.attachment-diagnostic ol{list-style:none;margin:0;padding:0}.attachment-diagnostic li{display:flex;gap:12px;padding:12px 0;border-bottom:1px solid #edf1ee}.attachment-diagnostic li>span{width:24px;height:24px;display:grid;place-items:center;border-radius:50%;background:#edf3ef}.attachment-diagnostic li[data-state=pass]>span{color:#197354;background:#e7f4ed}.attachment-diagnostic li[data-state=fail]>span{color:#b24444;background:#fff0ef}.attachment-diagnostic li[data-state=warning]>span{color:#91611c;background:#fff6df}.attachment-diagnostic li p{margin:6px 0;line-height:1.6}.attachment-diagnostic small,.environment{color:#738078;font-size:12px}.attachment-diagnostic details{margin-top:15px;font-size:12px}.attachment-diagnostic summary{cursor:pointer}.attachment-diagnostic textarea{box-sizing:border-box;width:100%;min-height:160px;margin-top:10px;font:12px/1.5 monospace}.attachment-diagnostic footer{display:flex;flex-wrap:wrap;gap:12px;justify-content:space-between;padding:16px 24px;border-top:1px solid #e6ece8}.attachment-diagnostic footer>div{display:flex;gap:8px;flex-wrap:wrap}.attachment-diagnostic button{border:1px solid #d6e1da;border-radius:7px;padding:8px 11px;background:#fff;color:inherit;cursor:pointer}.attachment-diagnostic button:disabled{opacity:.45;cursor:default}.attachment-diagnostic .primary{background:#147454;color:white}.notice{padding:10px;background:#f0f5f2;border-radius:7px}
</style>
